from 写入第二遍 import add
add('22_001',1.5,'16:9，略高机位青头顶与上背的近景，发根居画面中央，下垂刘海遮住脸，两肩留在下缘；固定机位。','青刚抬过一点的头重新垂到底，发束从胸前又往前滑了一截；肩膀先轻晃，随后两侧同时向前松开，背脊失去绷劲。她的重量越过双膝的支撑线，长发尖端先向地面垂落，上身接着向前倾出。','头肩外侧为浅冷灰图形底，米灰薄尘在下边形成柔软淡层。','上方冷白云光落在发顶，发内深浅灰分层，肩侧光线稳定。','发丝滑过衣领的细擦，短短呼气往下落，衣料随前倾一声软折。',phase='process',node={'叙事阶段':'青头完全低下，身体失去向前支撑'},meaning='垂头遮脸、肩晃与向前失力的原格阶段保留。',motion='头与肩先垂，再向前倾，发束沿重力滑落。',ground='双膝仍着地，重心正越出膝部支撑。',characters=['青'])
add('22_002',2.5,'16:9，越董白近侧肩胸看平台远处的全景，黑裙轮廓占画面左侧近层，青在中央后层；固定机位，青伏倒的位置和两侧尘团清楚。','青从跪姿向前倒，前臂和肘侧先软软落到石面，头随上身低下，脸侧贴住地；长发被压住一部分，其余向左右铺开，细尘在肩头两侧鼓起小团。她落定后双腿松展，只有呼吸还轻轻牵动肩背；董白近层身体僵了一小拍，肩线向青的方向微倾。','灰绿石铺地面在两人之间延伸，近处石块纹理清楚，青身侧米灰小尘团向外摊平；远层渐淡为浅冷灰云雾。','冷白云光均匀覆盖平台，黑裙近层压深，青银发与石面柔亮，尘边浅米灰。','肘侧与衣料落石的一声软闷响，头发铺地细擦，尘团轻散。',phase='result',node={'叙事阶段':'青向前伏倒，脸侧贴地','青.状态':'伏地，仍能答话','青.支撑':'石面与弯在头侧的前臂','董白.位置':'前层站着看，尚未扶起青'},meaning='用户确认的前伏倒地，董白前层与青远层构图保留，此时青仍清醒。',motion='青由上向前倒，发与尘向两侧散；董白未进入倒地位置。',ground='青上身、前臂与腿部落在石面，未发生新的攻击。',characters=['青','董白'])
add('22_003',3.5,'16:9，从青倒地高度略仰看董白的正面头肩近景，脸居画面中央，双马尾沿左右垂下；固定机位，圆眼与小圆口清楚。','董白低头盯着地上的青，眼珠向下移，眉尖一高一低，嘴先松开又抿了一下；她把第一个问句说得有些迟疑，没等到立刻回应，头朝另一边偏了一点。催她说话时，董白把下巴往前送，手指在画外裙侧轻扣，眼睛仍圆睁着等。','双马尾两侧露出蓝灰云天，浅灰云层从左向右缓慢漂移。','上方冷白漫射，董白脸下侧有石面中性弱补光，黑发反光细窄。','发尾随偏头扫过衣肩，空地风声在问句间短短露出。',ja=['…死んでないわよね？何か言いなさい。'],tone='董白先试探地问，停一小拍再带命令感催回应，紧张留在圆眼里。',kind='mixed',phase='reaction',node={'叙事阶段':'董白向伏地的青试探问话'},meaning='董白圆眼微张口、轻偏头的原格反应保留，话对倒地青说。',characters=['董白'],card={'opening':'她不确定青突然倒下后的状态。','beats':['低头圆眼试探问','未立即回应时偏头，催她开口'],'coupling':'短暂等待让命令语气里透出担心。','landing':'她停住盯看，等地上的青回答。'})
